'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),E=FrontierEngine,TYPES=E.TYPES,W=1000,H=760,TAU=Math.PI*2;
let game,g,selected=-1,chosen=0,aiming=false,aimPoint={x:500,y:350},last=0,uiClock=0,muted=false,audio,lastTone=0,shake=0,fx=[],floats=[],decals=[],beams=[],bannerTimer=0,best=0,frame=0;
const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
try{best=Number(localStorage.getItem('frontier-best-v2')||0)}catch{}
const terrain=new Image();terrain.src='terrain.png';
const roman=n=>['','I','II','III','IV'][n]||n,percent=(a,b)=>Math.ceil(a/b*100),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function tone(f=300,d=.08,type='triangle',volume=.035,force=false){if(muted)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();if(!force&&audio.currentTime-lastTone<.075)return;lastTone=audio.currentTime;const o=audio.createOscillator(),a=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,f*.45),audio.currentTime+d);a.gain.setValueAtTime(volume,audio.currentTime);a.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(a);a.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
let toastUntil=0;function say(text){$('toast').textContent=text;toastUntil=(g?.clock||0)+5}
function banner(text){$('combatBanner').textContent=text;$('combatBanner').classList.add('visible');bannerTimer=2.8}
function burst(x,y,color,n=12,smoke=false){for(let i=0;i<n;i++){const a=Math.random()*TAU,v=25+Math.random()*140;fx.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,z:smoke?10:Math.random()*10,vz:35+Math.random()*65,life:smoke?1.5:.35+Math.random()*.5,max:smoke?1.5:.85,color,size:smoke?10+Math.random()*12:2+Math.random()*3,smoke})}if(fx.length>400)fx.splice(0,fx.length-400)}
function ring(x,y,color,radius=70){fx.push({x,y,color,radius,life:.5,max:.5,ring:true})}
function event(e){switch(e.type){case'message':say(e.text);break;case'wave':banner('ONDA '+e.wave+' · '+e.name.toUpperCase());tone(160,.55,'sawtooth',.04,true);break;case'boss':banner(e.name.toUpperCase()+' DETECTADO');tone(75,.75,'sawtooth',.065,true);break;case'rage':banner('A MATRIARCA ENTROU EM FÚRIA');tone(80,.5,'sawtooth',.06,true);break;case'warning':say(e.text);banner('IMPACTO ALIENÍGENA IMINENTE');break;case'cleared':banner('ONDA REPELIDA · +'+e.bonus+' ◆');tone(900,.25,'sine',.04,true);break;case'coreHit':shake=Math.max(shake,5);floats.push({x:500+(Math.random()-.5)*25,y:605,text:'−'+Math.round(e.damage),color:'#ff9284',life:1});burst(500,610,'#ff9171',5);tone(70,.15,'sawtooth',.05);break;case'towerHit':burst(e.x,e.y-8,'#ffb46c',4);if(e.damage>=15)floats.push({x:e.x,y:e.y-35,text:'−'+Math.round(e.damage),color:'#ffb49c',life:.7});break;case'destroyed':shake=Math.max(shake,9);burst(e.x,e.y,'#ffb96c',24);burst(e.x,e.y,'#5c6474',8,true);ring(e.x,e.y,'#ffad67',65);decals.push({x:e.x,y:e.y,size:35,color:'#101922',life:40});tone(65,.35,'sawtooth',.07,true);break;case'kill':burst(e.x,e.y,e.color,e.big?35:10);decals.push({x:e.x,y:e.y,size:e.big?30:11,color:'#393728',life:18});if(e.big){shake=Math.max(shake,10);burst(e.x,e.y,'#5c5769',12,true);tone(60,.5,'sawtooth',.07,true)}break;case'explosion':burst(e.x,e.y,e.color,e.ice?8:15);ring(e.x,e.y,e.color,e.radius);if(!e.ice){shake=Math.max(shake,2);tone(100,.13,'sawtooth',.025)}break;case'orbital':shake=15;burst(e.x,e.y,'#adfaff',40);burst(e.x,e.y,'#8588a8',12,true);ring(e.x,e.y,'#a1f1ff',e.radius*1.3);beams.push({x:e.x,y:e.y,tx:e.x-30,ty:-50,color:'#c0ffff',life:.5,max:.5,width:18});tone(55,.6,'sawtooth',.08,true);break;case'shield':ring(500,620,'#7bcfff',180);tone(580,.35,'sine',.05,true);break;case'shot':tone(e.type===1?100:e.type===3?560:270,.06,e.type===1?'sawtooth':'triangle',.018);break;case'coreShot':beams.push({x:500,y:600,tx:e.x,ty:e.y,color:'#b8ffec',life:.12,max:.12,width:2});break;case'slash':ring(e.x,e.y,e.color,25);break;case'acidHit':burst(e.x,e.y,'#ff966f',8);decals.push({x:e.x,y:e.y,size:12,color:'#69512c',life:7});break;case'impact':burst(e.x,e.y,e.color,3);break;case'build':case'upgrade':burst(e.x,e.y,e.color,14);tone(650,.15,'sine');break;case'repair':tone(450,.12,'sine');break;case'research':tone(950,.25,'sine',.04,true);break;case'focus':say(e.text);tone(500,.07);break;case'end':endScreen(e.won);break}if(decals.length>80)decals.shift();if(floats.length>40)floats.shift()}
function reset(){game=E.create({onEvent:event});g=game.state;selected=-1;chosen=0;aiming=false;fx=[];floats=[];decals=[];beams=[];shake=0;ui()}
function playing(){return g.mode==='prep'||g.mode==='battle'}
function choose(i){if(!playing()||g.paused)return;if(g.tier<TYPES[i].tier){say('Pesquise Tecnologia II para liberar o Plasma.');return}chosen=i;selected=-1;aiming=false;say('Toque numa plataforma ＋ para construir '+TYPES[i].name+'.');ui()}
function perform(fn){const r=fn();ui();return r}
function setAim(){if(aiming){aiming=false;ui();return}if(g.mode!=='battle'||g.paused||g.energy<50||g.pulseCd>0){say('O bombardeio exige 50 de energia e precisa estar recarregado.');return}aiming=true;say('Toque onde os invasores estarão: o bombardeio atinge uma área.');ui()}
function endScreen(won){aiming=false;best=Math.max(best,won?12:g.wave-1);try{localStorage.setItem('frontier-best-v2',best)}catch{}$('overlay').hidden=false;$('overlay').innerHTML='<div class="modal"><span class="eyebrow">'+(won?'A EVACUAÇÃO FOI CONCLUÍDA':'O NÚCLEO FOI DESTRUÍDO')+'</span><h2>'+(won?'A Terra resistiu.<br><em>Graças a você.</em>':'A linha caiu.<br><em>A resistência continua.</em>')+'</h2><p>'+(won?'Você enfrentou o cerco e derrotou a Matriarca. A rota de evacuação está aberta.':'Onda '+g.wave+': '+E.WAVES[g.wave-1].tip)+'</p><div class="steps"><span>'+g.kills+' invasores abatidos · '+g.metrics.towersLost+' torres perdidas</span><span>'+Math.round(g.metrics.coreDamage)+' de dano recebido pelo núcleo</span><span>Recorde neste dispositivo: '+best+' ondas concluídas</span></div><button class="primary" id="restart">TENTAR NOVA ESTRATÉGIA ↗</button></div>';$('restart').onclick=()=>{reset();game.start();$('overlay').hidden=true;ui()};tone(won?900:60,.8,'sawtooth',.04,true);ui()}
