 const t=g.buildings[selected]?.tower;const c=game.upgradeCost(selected),rc=game.repairCost(selected),busy=t&&(t.build>0||t.upgrade>0);const name=t?TYPES[t.type].name+' · nível '+t.level:'Nenhuma torre selecionada';$('selectedName').textContent=name;$('selectedInfo').textContent=t?'Integridade '+Math.ceil(t.hp)+' / '+t.maxHp.toFixed(0)+(t.build>0?' · construindo: '+Math.ceil(t.build)+'s':t.upgrade>0?' · evoluindo: '+Math.ceil(t.upgrade)+'s':t.repair>0?' · reparando: '+Math.ceil(t.repair)+'s':' · '+TYPES[t.type].role):'Toque em uma torre para reparar ou evoluir. Toque em um inimigo para marcar o alvo.';
