function poly(points,fill,stroke){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function ellipse(x,y,rx,ry,c){if(rx<=0||ry<=0)return;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);ctx.fillStyle=c;ctx.fill()}
function line(x,y,tx,ty,color,w=1){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(tx,ty);ctx.strokeStyle=color;ctx.lineWidth=w;ctx.stroke()}
function bar(x,y,w,ratio,color){ctx.fillStyle='#07121ce8';ctx.fillRect(x-w/2-1,y-1,w+2,7);ctx.fillStyle=color;ctx.fillRect(x-w/2,y,w*Math.max(0,Math.min(1,ratio)),5)}
