 if(t.repair>0){const a=g.clock*3;ellipse(Math.cos(a)*29,Math.sin(a)*13-43,8,4,'#93bccc');line(Math.cos(a)*29,Math.sin(a)*13-41,0,-10,'#6dffdbaa',2)}
 if(selected===i){ctx.strokeStyle=d.color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,39,28,0,0,TAU);ctx.stroke()}
