function drawHazard(h){const progress=1-h.left/h.total;ctx.save();ctx.translate(h.x,h.y);const color=h.friendly?'#98ffee':'#ff7284';ctx.fillStyle=h.friendly?'#72ffe519':'#ff50692b';ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,h.radius,h.radius*.72,0,0,TAU);ctx.fill();ctx.stroke();ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,h.radius,h.radius*.72,0,-Math.PI/2,-Math.PI/2+TAU*progress);ctx.stroke();line(-12,0,12,0,color,2);line(0,-12,0,12,color,2);ctx.fillStyle=color;ctx.font='bold 15px Arial';ctx.textAlign='center';ctx.fillText(h.friendly?'IMPACTO':'PERIGO · '+h.left.toFixed(1)+'s',0,-h.radius*.72-10);ctx.restore()}
