function animateFx(dt){if(g.paused)return;shake=Math.max(0,shake-dt*22);for(const f of fx){f.life-=dt;if(!f.ring){f.x+=f.vx*dt;f.y+=f.vy*dt;f.z+=f.vz*dt;f.vz-=dt*(f.smoke?0:150)}}fx=fx.filter(f=>f.life>0);for(const f of floats){f.life-=dt;f.y-=dt*28}floats=floats.filter(f=>f.life>0);for(const d of decals)d.life-=dt;decals=decals.filter(d=>d.life>0);for(const b of beams)b.life-=dt;beams=beams.filter(b=>b.life>0);bannerTimer-=dt;if(bannerTimer<=0)$('combatBanner').classList.remove('visible');if(playing()&&frame%12===0){for(const s of g.buildings)if(s.tower&&s.tower.hp<s.tower.maxHp*.45)burst(s.x+12,s.y-25,'#616b76',1,true);if(g.hp<360)burst(465,610,'#676971',1,true)}}
function loop(time){const dt=Math.min((time-last)/1000||0,.05);last=time;frame++;for(let i=0;i<g.speed;i++)game.step(dt);animateFx(dt*g.speed);draw();uiClock+=dt;if(uiClock>.12){uiClock=0;ui()}requestAnimationFrame(loop)}
$('towerCards').innerHTML=TYPES.map((t,i)=>'<button class="tower" data-type="'+i+'" style="--accent:'+t.color+'" aria-pressed="false"><span class="symbol">'+t.icon+'</span><div><b>'+t.name+'</b><small>'+t.role+'</small></div><strong data-cost>'+t.cost+' ◆</strong></button>').join('');$('quickBuild').innerHTML=TYPES.map((t,i)=>'<button data-type="'+i+'" aria-pressed="false">'+t.icon+' '+t.name+'<small data-cost>'+t.cost+' ◆</small></button>').join('');document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.type)));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',t===b));$('defenses').hidden=b.dataset.tab!=='defenses';$('research').hidden=b.dataset.tab!=='research'});
function coordinates(ev){const r=canvas.getBoundingClientRect();return {x:(ev.clientX-r.left)/r.width*W,y:(ev.clientY-r.top)/r.height*H}}
canvas.addEventListener('pointermove',ev=>{if(aiming)aimPoint=coordinates(ev)});canvas.addEventListener('pointerdown',ev=>{if(!playing()||g.paused)return;const p=coordinates(ev);if(aiming){const r=game.pulse(p.x,p.y);if(r.ok)aiming=false;ui();return}let index=-1,distance=48;g.buildings.forEach((s,i)=>{const d=dist(s,p);if(d<distance){distance=d;index=i}});const enemy=g.enemies.filter(e=>!e.dead).map(e=>({e,d:Math.hypot(e.x-p.x,(e.y-(E.ENEMIES[e.type].air?28:0))-p.y)})).sort((a,b)=>a.d-b.d)[0];if(enemy&&enemy.d<Math.max(25,E.ENEMIES[enemy.e.type].size)&&enemy.d<distance){perform(()=>game.focus(enemy.e.id));return}if(index>=0){const s=g.buildings[index];if(s.tower){selected=index;chosen=-1;ui()}else if(chosen>=0){const r=game.build(index,chosen);if(r.ok)selected=index;ui()}else say('Escolha uma defesa para construir nesta plataforma.')}else if(enemy&&enemy.d<45)perform(()=>game.focus(enemy.e.id));else{selected=-1;ui();say('Toque em ＋ para construir ou em um inimigo para concentrar fogo.')}});
$('repairLine').onclick=()=>perform(game.repairLine);$('start').onclick=()=>{game.start();$('overlay').hidden=true;tone(660,.2,'sine',.04,true);ui()};$('next').onclick=()=>perform(game.nextWave);$('upgrade').onclick=$('quickUpgrade').onclick=()=>perform(()=>game.upgrade(selected));$('repairTower').onclick=$('quickRepair').onclick=()=>perform(()=>game.repair(selected));$('sell').onclick=()=>perform(()=>game.sell(selected));for(const k of ['age','damage','repair','income','armor'])$(k).onclick=()=>perform(()=>game.research(k));$('pulse').onclick=$('quickPulse').onclick=setAim;$('shield').onclick=$('quickShield').onclick=()=>perform(game.shield);$('cancelAim').onclick=()=>{aiming=false;ui()};$('pause').onclick=()=>{game.togglePause();ui()};$('speed').onclick=()=>{g.speed=g.speed===1?2:1;ui()};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'Som: off':'Som: on';$('sound').setAttribute('aria-label',muted?'Ativar som':'Desativar som');tone(500,.1)};
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea'))return;if(e.code==='Space'){if(e.target.closest('button'))return;e.preventDefault();$('pause').click()}if(e.key>='1'&&e.key<='4')choose(Number(e.key)-1);if(e.key.toLowerCase()==='e')$('upgrade').click();if(e.key.toLowerCase()==='r')$('repairTower').click();if(e.key.toLowerCase()==='b')setAim();if(e.key.toLowerCase()==='s')$('shield').click();if(e.key==='Escape'){aiming=false;ui()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing()){g.paused=true;ui()}});
reset();requestAnimationFrame(loop);
if(document.modelContext?.registerTool){const lifecycle=new AbortController(),state=()=>({wave:g.wave,phase:g.mode,paused:g.paused,credits:Math.floor(g.credits),baseHealth:g.hp,technology:g.tier,energy:g.energy,kills:g.kills,towersLost:g.metrics.towersLost,platforms:g.buildings.map((s,index)=>({index,tower:s.tower?{name:TYPES[s.tower.type].name,level:s.tower.level,hp:s.tower.hp,maxHp:s.tower.maxHp}:null}))});const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_defense_state',description:'Read the active defense game, actual structure health and resources.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:state});register({name:'build_defense',description:'Spend credits and begin constructing a defense on an empty platform in the active game.',inputSchema:{type:'object',properties:{platform:{type:'integer',minimum:0,maximum:11},type:{type:'integer',minimum:0,maximum:3}},required:['platform','type'],additionalProperties:false},execute:input=>{if(!input||!Number.isInteger(input.platform)||!Number.isInteger(input.type))throw Error('Invalid input');const r=game.build(input.platform,input.type);if(!r.ok)throw Error(r.message||'Construction unavailable');selected=input.platform;ui();return state()}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
